css:
.cycle{position:relative;aspect-ratio:1;max-width:420px;margin-inline:auto}
.cycle>svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:1}
.cycle__node{position:absolute;width:38%;aspect-ratio:1;border-radius:50%;z-index:2;
  display:grid;place-items:end center;text-align:center}
.cycle__core{position:absolute;left:50%;top:50%;translate:-50% -50%;
  width:30%;aspect-ratio:1;border-radius:50%;background:#f6e96b;z-index:3;display:grid;place-items:center}

